#!/bin/sh
set -eu
test "$#" -eq 1
if command -v python >/dev/null 2>&1; then interpreter=python; else interpreter=python3; fi
"$interpreter" - "$1" <<'PY'
import base64
from pathlib import Path
import sys
Path(sys.argv[1]).write_bytes(base64.b64decode(''))
print('RESTORED_PRISTINE_MAINACTIVITY')
PY
